      id: i,
      src: SOC_CORPUS[o],
      dstPort: SOC_CORPUS[o + 1] % 65536,
      bytes: SOC_CORPUS[o + 2],
      severity: SOC_CORPUS[o + 3] % 5,
      flags: SOC_CORPUS[o + 4],
      ts: SOC_CORPUS[o + 5]
