  var max = 0;
  var buckets = [];
  var i;
  for (i = 0; i < 16; i++) buckets.push(0);
  for (i = 0; i < scored.length; i++) {
    var item = scored[i];
    sum += item.score;
    if (item.score > max) max = item.score;
    hist[item.event.severity]++;
    buckets[item.event.src & 15]++;
  }
