function bootType(bootOut) {
  var intelText = socOpenIntel();
  SOC_INTEL = socParse(intelText);
  check('soc.intel.digest', hashText(intelText) === W_INTEL_DIGEST);
  var events = socBuildCorpus();
  check('soc.corpus.digest', socCorpusDigest() === SOC_CORPUS_DIGEST);
  check('soc.corpus.count', events.length === W_CORPUS_EVENTS);
  var first = socEvaluate(events, SOC_RULES, Number(SOC_INTEL.threshold));
  var second = socEvaluate(events, SOC_RULES, Number(SOC_INTEL.threshold));
  var same = first.scored.length === second.scored.length;
  for (var i = 0; i < first.scored.length && same; i++) {
    if (first.scored[i].score !== second.scored[i].score || first.scored[i].hits !== second.scored[i].hits) same = false;
  }
  check('soc.rules.deterministic', same === true);
  var risk = socRisk(first.scored);
  SOC_RISK = risk;
  var limit = Number(SOC_INTEL.maxRows);
  var top = socTriage(first.scored, limit);
  check('soc.triage.rows', top.length === limit);
  check('soc.risk.mean', risk.mean >= 0);
  var state = 'steady';
  if (risk.max > 900) state = 'critical';
  else if (risk.max > 600) state = 'elevated';
  SOC_STATE = state;
  var lines = [];
  lines.push(socPad('id', 5) + socPad('src', 12) + socPad('sev', 5) + socPad('score', 7) + socPad('hits', 5) + 'port');
  for (i = 0; i < top.length; i++) {
    var t = top[i];
    lines.push(socPad(t.event.id, 5) + socPad('0x' + t.event.src.toString(16), 12) + socPad(t.event.severity, 5) + socPad(t.score, 7) + socPad(t.hits, 5) + t.event.dstPort);
  }
  return {
    print: function () {
      console.log('[SOC] console corpus=' + events.length + ' events rules=' + SOC_RULES.length + ' ruleOps=' + (SOC_RULES.length * SOC_RULES[0].length / 2));
      console.log('[SOC] intel=' + intelText + ' digest=' + hashText(intelText).toString(16) + '/' + W_INTEL_DIGEST.toString(16));
      console.log('[SOC] triage top=' + top.length + ' totalHits=' + first.totalHits);
      for (var k = 0; k < lines.length; k++) console.log('[SOC] ' + lines[k]);
      console.log('[SOC] risk mean=' + (Math.round(risk.mean * 100) / 100) + ' max=' + risk.max + ' high=' + risk.high + ' entropy=' + (Math.round(risk.entropy * 1000) / 1000) + ' state=' + state);
      console.log('[SOC] severity histogram=' + risk.hist.join('/'));
    }
  };
}

